import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/dtc-editor.jpg",d="/bilder/tos-rechner.jpg",b=JSON.parse('{"title":"DTC – Cartridges","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/dtc.md","filePath":"bereiche/dtc.md"}'),s={name:"bereiche/dtc.md"};function o(l,e,g,h,u,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="dtc-–-cartridges" tabindex="-1">DTC – Cartridges <a class="header-anchor" href="#dtc-–-cartridges" aria-label="Permalink to &quot;DTC – Cartridges&quot;">​</a></h1><p>Seit DCS den <strong>Data Transfer Cartridge</strong> kennt, lädt der Jet Steerpoints, Funk und Gegenmaßnahmen aus einer Datei. Shardwing baut diese Cartridges für <strong>F-16C</strong> und <strong>F/A-18C</strong> – im nativen DCS-Format, als läge sie im DTC-Manager des Mission Editors.</p><p><img src="'+a+'" alt="DTC-Editor einer F-16C mit Steerpoints, Zielen und Bedrohungsringen auf der Karte" loading="lazy"></p><h2 id="eine-cartridge-anlegen" tabindex="-1">Eine Cartridge anlegen <a class="header-anchor" href="#eine-cartridge-anlegen" aria-label="Permalink to &quot;Eine Cartridge anlegen&quot;">​</a></h2><p>Reiter <strong>DTC</strong> eines Flights:</p><table tabindex="0"><thead><tr><th>Knopf</th><th>Was passiert</th></tr></thead><tbody><tr><td><strong>Neu aus Route</strong></td><td>Übernimmt die Wegpunkte als Steerpoints, die Funk-Presets und <strong>nur die Bedrohungen, die für diesen Flight freigegeben sind</strong>. CMDS bleibt standardmäßig beim Piloten. Die übliche Wahl.</td></tr><tr><td><strong>Neu leer</strong></td><td>Leere Cartridge – mit Funk, CMDS und Schaltern aus deiner Standard-Cartridge, falls du eine festgelegt hast.</td></tr><tr><td><strong>Aus Datei …</strong></td><td>Eine vorhandene <code>.dtc</code> laden, z. B. die eigene aus <code>Saved Games\\DCS\\DTC</code>.</td></tr></tbody></table><p>Eine Cartridge in der Mission ist eine <strong>Datei in der .miz</strong>. Sie hängt an einem oder mehreren Flugzeugen; im Kopf des Editors siehst du, an welchen (<em>an Aerial-1</em>). Mehrere Flights können sich eine Cartridge teilen.</p><h2 id="der-kopf-des-editors" tabindex="-1">Der Kopf des Editors <a class="header-anchor" href="#der-kopf-des-editors" aria-label="Permalink to &quot;Der Kopf des Editors&quot;">​</a></h2><ul><li><strong>Name</strong> – wird der Dateiname in der .miz.</li><li><strong>an …</strong> – welche Units des Flights die Cartridge laden.</li><li><strong>AutoLoad</strong> – lädt beim Spawn automatisch. Ohne AutoLoad lädt der Pilot sie selbst auf der DTE-Seite (F-16) bzw. MUMI-Seite (F/A-18).</li><li><strong>Als meine Standard-Cartridge</strong> – Funk, CMDS und Schalter dieser Cartridge werden die Vorlage für <em>Neu leer</em> (ohne Wegpunkte, Linien, Threats).</li><li><strong>.dtc exportieren</strong> – als einzelne Datei speichern, z. B. für <code>Saved Games\\DCS\\DTC</code>.</li><li><strong>Entfernen</strong> – Cartridge aus der Mission nehmen.</li></ul><h2 id="bereiche-und-„uberschreiben" tabindex="-1">Bereiche und „überschreiben“ <a class="header-anchor" href="#bereiche-und-„uberschreiben" aria-label="Permalink to &quot;Bereiche und „überschreiben“&quot;">​</a></h2><p>Eine Cartridge besteht aus Bereichen (NAV, COMM, CMDS …). Jeder Bereich hat den Schalter <strong>überschreiben</strong>:</p><ul><li><strong>an</strong> – wird beim Laden in den Jet geschrieben.</li><li><strong>aus</strong> – fehlt in der .dtc; der Jet behält, was er hat.</li></ul><p>So kannst du z. B. Steerpoints und Funk vorgeben, aber die <strong>CMDS-Programme des Piloten unangetastet</strong> lassen.</p><p><strong>Übernehmen aus …</strong> holt einen Bereich aus einer anderen Cartridge – etwa die eigenen CMDS-Programme.</p><h2 id="f-16c" tabindex="-1">F-16C <a class="header-anchor" href="#f-16c" aria-label="Permalink to &quot;F-16C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Steerpoints</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>NAV</strong></td><td>1–24</td><td>Steerpoints mit Koordinate, Elevation, TOS, Offset Aimpoints (OA1/OA2), Zuordnung zu Route 1–3. Steerpoint 25 ist der Bullseye.</td></tr><tr><td><strong>Geo Lines</strong></td><td>31–55</td><td>Linien auf dem HSD – aus Zeichnungen (FLOT, Kill Box, CAP …) übernommen oder von Hand gesetzt, bis zu vier Linien.</td></tr><tr><td><strong>Threats</strong></td><td>56–70</td><td>Threat-Ringe mit DCS-Typ und Reichweite – nur freigegebene.</td></tr><tr><td><strong>DEST</strong></td><td>81–99</td><td>Zielpunkte, z. B. Flugplätze.</td></tr><tr><td><strong>VIP/VRP</strong></td><td>je 1</td><td>Visual Initial Point bzw. Visual Reference Point mit Peilung/Distanz/Elevation zu Ziel und PUP.</td></tr><tr><td><strong>COMM</strong></td><td>–</td><td>COMM1 (UHF) und COMM2 (VHF/FM), 20 Presets je Radio.</td></tr><tr><td><strong>CMDS</strong></td><td>–</td><td>Chaff/Flare-Programme. Standard: <em>nicht überschreiben</em>.</td></tr></tbody></table><h3 id="steerpoints-bearbeiten" tabindex="-1">Steerpoints bearbeiten <a class="header-anchor" href="#steerpoints-bearbeiten" aria-label="Permalink to &quot;Steerpoints bearbeiten&quot;">​</a></h3><ul><li><strong>Klick auf die Karte</strong> setzt einen neuen Steerpoint, ziehen verschiebt ihn.</li><li>In der Tabelle: Typ, Notiz, Koordinate, <strong>Elev ft</strong>, <strong>TOS</strong>, OA1/OA2 und die Routen (1, 2, 3 – wie im DTC-Manager).</li><li><strong>Elev = Boden (alle)</strong> setzt die Elevation aller Punkte aus Geländedaten (SRTM, kann von DCS um ein paar Meter abweichen).</li><li><strong>TOS verschieben</strong> um ±1 oder ±5 Minuten, <strong>TOS aus Route</strong> übernimmt die ETAs der Missionsroute. TOS wird in Zulu gespeichert; <kbd>↑</kbd>/<kbd>↓</kbd> im Zeitfeld verstellt die Stelle unter dem Cursor, mit <kbd>Shift</kbd> in Zehnerschritten.</li><li>Pfeile ↑ ↓ ändern die Reihenfolge, × löscht.</li></ul><h3 id="tos-rechner" tabindex="-1">TOS-Rechner <a class="header-anchor" href="#tos-rechner" aria-label="Permalink to &quot;TOS-Rechner&quot;">​</a></h3><p>Über der Steerpoint-Tabelle (NAV). Er füllt die TOS aller Steerpoints der Route 1 aus den Sollzeiten des Designers (Push, TOT bzw. On Station und weitere wie RV), damit niemand jede Zeit von Hand ausrechnen muss.</p><p><img src="'+d+'" alt="TOS-Rechner von ELI 1: Push und SEAD-Beginn als feste Zeiten, Halten am Tanker und am Push-Punkt, orange markierte Geschwindigkeiten" loading="lazy"></p><ol><li><strong>Sollzeiten zuordnen</strong> – für jede Sollzeit den Steerpoint wählen, an dem ihr sie erreicht. Push und Ziel sind mit den Punkten des Designers vorbelegt. Die Zeiten selbst ändert nur der Designer (🔒). Hat eine Sollzeit einen Ort (📍), springt der gewählte Steerpoint dorthin; liegt er später daneben, setzt ihn <strong>📍 … NM daneben – setzen</strong> zurück. Hat die Sollzeit ein Höhenband (z. B. <em>FL180–190</em> am Marshal), steht es daneben, und der Steerpoint bekommt die Unterkante als Routenhöhe. Steht bei der Zeit <em>ohne Zeit</em>, will der Designer nur, dass ein Steerpoint dort liegt; für die TOS zählt er nicht. <strong>AAR-Slots</strong> (ℹ) stehen nur zur Info dabei: Sie zählen erst, wenn ihr einen Steerpoint wählt, und es gibt keine Warnung, wenn ihr sie weglasst. Hat der Tanker einen Track, zeigt 📍 dessen Anfang; liegt der gewählte Steerpoint woanders, setzt <strong>setzen</strong> ihn dorthin.</li><li><strong>Eigene feste Zeiten</strong> – in der Spalte <em>Feste Zeit</em>, z. B. „am Holding um 07:20“. Das ist die Ankunftszeit.</li><li><strong>Halten</strong> – Minuten, die ihr an einem Steerpoint kreist. Am Push-Punkt heißt das: früher da sein, kreisen, zur Push-Zeit los.</li><li><strong>Geschwindigkeit</strong> – gilt vor der ersten und nach der letzten festen Zeit (Standard: Mittel der Missionsroute). Dazwischen fliegt ihr eine gleichmäßige Geschwindigkeit; die Spalte <em>GS</em> zeigt sie, unter 250 oder über 600 kt gibt es einen Hinweis.</li><li><strong>TOS übernehmen</strong> schreibt die Zeiten in die Cartridge (Rückgängig mit <kbd>⌘Z</kbd> / <kbd>Strg+Z</kbd>). Von selbst rechnet nichts neu.</li></ol><p>Ohne Sollzeiten rechnet der Rechner ab dem Start der Mission. Oben steht, wann ihr dafür abheben müsst. Weichen eure TOS von einer Sollzeit ab, sieht der Designer das im <a href="./timing">Timing</a>. Für die F/A-18C gibt es den Rechner noch nicht.</p><h3 id="geo-lines-aus-zeichnungen" tabindex="-1">Geo Lines aus Zeichnungen <a class="header-anchor" href="#geo-lines-aus-zeichnungen" aria-label="Permalink to &quot;Geo Lines aus Zeichnungen&quot;">​</a></h3><p><strong>Aus Grafik übernehmen …</strong> bzw. <strong>Aus Zeichnung übernehmen</strong> macht aus einer FLOT, Kill Box oder CAP-Station eine Geo Line – in die nächste freie Linie oder an eine bestimmte angehängt. Flächen werden geschlossen, Racetracks gestuft.</p><h2 id="f-a-18c" tabindex="-1">F/A-18C <a class="header-anchor" href="#f-a-18c" aria-label="Permalink to &quot;F/A-18C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>Waypoints</strong></td><td>1–59, Route 1</td></tr><tr><td><strong>SA-Seite</strong></td><td>CAP-Punkte (Racetrack mit Anker, Kurs, Leg, Kurve links/rechts), FLOT, FAOR und Korridor, MEZ-Ringe (Threats)</td></tr><tr><td><strong>COMM</strong></td><td>Presets mit Kanalnamen, die auf dem UFC erscheinen. Die Hornet nimmt UHF und VHF auf beiden Radios.</td></tr><tr><td><strong>TACAN</strong></td><td>wird unverändert aus der Datei übernommen; ein Editor folgt</td></tr><tr><td><strong>CMDS</strong></td><td>ALR-67-Programme</td></tr></tbody></table><h2 id="comm" tabindex="-1">COMM <a class="header-anchor" href="#comm" aria-label="Permalink to &quot;COMM&quot;">​</a></h2><p>Jede Station auf jedem Kanal, im Band nach Wahl. Die F-16 nimmt auf COMM1 nur UHF, auf COMM2 VHF/FM; die Hornet beides. Einfacher als Kanal für Kanal: den paketweiten <a href="./kneeboards#comm-plan">Comm Plan</a> anlegen und mit einem Knopf in alle Cartridges übernehmen.</p><h2 id="personliche-cartridges" tabindex="-1">Persönliche Cartridges <a class="header-anchor" href="#personliche-cartridges" aria-label="Permalink to &quot;Persönliche Cartridges&quot;">​</a></h2><p>Beim gemeinsamen Planen teilen sich oft mehrere Flugzeuge eine Cartridge. Ändert ein Pilot <strong>seine CMDS oder Farben</strong>, legt Shardwing eine persönliche Kopie an (<code>&lt;Cartridge&gt; - &lt;Callsign&gt;</code>). Sein Jet lädt die Kopie, alle anderen behalten die gemeinsame. Eine Cartridge, die mehrere Flights laden, ändert nur der Designer – der Flight kann sich eine eigene Kopie anlegen.</p><h2 id="einzelne-cartridges" tabindex="-1">Einzelne Cartridges <a class="header-anchor" href="#einzelne-cartridges" aria-label="Permalink to &quot;Einzelne Cartridges&quot;">​</a></h2><p>Öffnest du eine <code>.dtc</code>-Datei ohne Mission, steht sie links unter <strong>Einzelne Cartridges</strong>. Du kannst sie bearbeiten und wieder als <code>.dtc</code> speichern – etwa deine persönliche Standard-Cartridge.</p>',33)])])}const p=t(s,[["render",o]]);export{b as __pageData,p as default};
